import { StrictMode } from "react";
import { createRoot } from "react-dom/client";

import { ComponentContext, getStudioProApi, IComponent, StudioProApi } from "@mendix/extensions-api";

import AppThemeProvider from "../components/AppThemeProvider";

import { createStudioProLogger } from "../../config/logger";
import { Headers } from "../../types/consumedMCPService";
import AuthenticationHeadersEditor from "./authenticationHeadersEditor";

interface AppProps {
    studioPro: StudioProApi;
    headers: Headers;
    onClose: (result: Headers | null) => void;
}
const App: React.FC<AppProps> = ({ studioPro, headers, onClose }) => {
    return (
        <AppThemeProvider studioPro={studioPro}>
            <AuthenticationHeadersEditor headers={headers} onClose={onClose} />
        </AppThemeProvider>
    );
};

export const component: IComponent = {
    async loaded(componentContext: ComponentContext, componentInput: { dialogId: string; headers: string }) {
        const studioPro = getStudioProApi(componentContext);
        const logger = createStudioProLogger(studioPro);

        if (!componentInput.headers) {
            throw new Error(
                "Authentication headers need to be provided to open the MCP authentication headers dialog."
            );
        }

        try {
            const headers: Headers = JSON.parse(decodeURIComponent(componentInput.headers));

            const rootElement = document.getElementById("root");
            if (!rootElement) {
                throw new Error("Failed to find the root element.");
            }

            const root = createRoot(rootElement);

            const handleClose = (result: Headers | null) => {
                // Set the result on the component context before closing
                studioPro.ui.dialogs.closeWithResult(componentInput.dialogId, result);
            };

            root.render(
                <StrictMode>
                    <App studioPro={studioPro} headers={headers} onClose={handleClose} />
                </StrictMode>
            );
        } catch (error) {
            logger.error("Error editing MCP authentication headers:", error);
            throw new Error("Error editing MCP authentication headers:", error as Error);
        }
    },
};
